#include <cstddef>
#include <vector>
#include <omp.h>

size_t findFirstEven(std::vector<int> const& x) {
    const size_t n = x.size();
    size_t first = n;  // If no even element exists, return x.size().

    #pragma omp parallel for reduction(min:first) schedule(static)
    for (size_t i = 0; i < n; ++i) {
        if ((x[i] & 1) == 0) {
            if (i < first) {
                first = i;
            }
        }
    }

    return first;
}
